    10  void setValidValues(std::vector<std::uint8_t>& boxData) {
    11    // The first 4 bytes correspond to the BR (Brand). It must have the value 'jp2\040'
    12    boxData[0] = 'j';
    13    boxData[1] = 'p';
    14    boxData[2] = '2';
    15    boxData[3] = '\040';
    16
    17    // The next 4 bytes correspond to the MinV (Minor version). It is a 4-byte unsigned int with value 0
    18
    19    // The only available Compatibility list also has the value 'jp2\040'
    20    boxData[8] = 'j';
    21    boxData[9] = 'p';
    22    boxData[10] = '2';
    23    boxData[11] = '\040';
    24  }
