    32  TEST(Jp2_FileTypeBox, isValidWithMinimumPossibleSizeAndValidValues) {
    33    std::vector<std::uint8_t> boxData(12);
    34    setValidValues(boxData);
    35    ASSERT_TRUE(isValidBoxFileType(boxData));
    36  }
